text:
Classical machine learning and statistical algorithms are hugely preferred in regulated sectors for example credit analytics or medical intelligence. The primary reason being, these are easier to explain. Easier to troubleshoot if something goes wrong.
But in case of deep neural networks, it becomes a bit fuzzy. Mostly these are treated as black boxes which emits absolutely no light of “how did it happen”. Now, this is only half true — at least for networks built out of ReLUs. A ReLU network is a piecewise linear function, and piecewise linear functions are things we can literally draw. This was first framed and introduced by Pascanu, Montúfar and Bengio (2013) and developed in On the Number of Linear Regions of Deep Neural Networks (2014) (Montúfar et al., NeurIPS 2014).
In this blog, i have tried to visualize a shallow network — one input, one hidden layer containing n numbers of ReLU units, one output. The one dimensional input space let us see the network plotted on a single axis and can be watched how it bends and fit the true function over multiple iterations. The interesting part is to see where the bends come from, why there can only be a handful of them, and how the network splits its input into regions where it behaves like a straight line. On top of that, how the goodness of fit for this network can critically be improved using this visual perspective.
This is a self-contained blog with code cells embedded. You can run the codes in parallel while going through it.
Lets import the necessary libraries and some helper functions for the experiments.

Libraries and Helper Functions


Show code
import graphviz
import matplotlib.pyplot as plt
import torch
import numpy as np
import torch.nn as nn
import json
from html import escape
import plotly.graph_objects as go
from plotly.subplots import make_subplots
from tqdm import tqdm
from IPython.display import HTML, display
import plotly.io as pio
pio.renderers.default = "plotly_mimetype+notebook_connected"


PALETTE = [
    ('#dbeafe', '#2563eb'),  # input   — blue
    ('#fef3c7', '#d97706'),  # hidden  — amber
    ('#dcfce7', '#16a34a'),  # output  — green
]
BIAS_FILL, BIAS_LINE = '#f3e8ff', '#7c3aed'   # purple, used nowhere else

def draw_nn(layers, node_labels=None, edge_labels=None, biases=None,
            palette=PALETTE, legend=True):
    g = graphviz.Digraph(
        graph_attr={'rankdir': 'LR', 'dpi': '120',
                    'ranksep': '1.3', 'nodesep': '0.45'},
        node_attr={'shape': 'circle', 'fixedsize': 'true', 'width': '0.65',
                   'fontsize': '11', 'style': 'filled', 'penwidth': '1.6'},
        edge_attr={'arrowsize': '0.5'})

    for i, n in enumerate(layers):
        fill, line = palette[i % len(palette)]
        with g.subgraph() as s:
            s.attr(rank='same')
            for j in range(n):
                s.node(f'{i}_{j}',
                       label=node_labels[i][j] if node_labels else f'{i}{j}',
                       fillcolor=fill, color=line, fontcolor=line)
            if biases and i &lt; len(layers) - 1:
                s.node(f'bias_{i}', label='1', shape='square', width='0.42',
                       fillcolor=BIAS_FILL, color=BIAS_LINE,
                       fontcolor=BIAS_LINE, fontsize='10')

    for i in range(len(layers) - 1):
        for a in range(layers[i]):
            for b in range(layers[i + 1]):
                w = edge_labels[i][a][b] if edge_labels else None
                g.edge(f'{i}_{a}', f'{i + 1}_{b}',
                       xlabel='' if w is None else f'{w}',
                       color='grey55', penwidth='1.3',
                       fontcolor='grey20', fontsize='9')
        if biases:
            for b in range(layers[i + 1]):
                bb = biases[i][b]
                g.edge(f'bias_{i}', f'{i + 1}_{b}',
                       xlabel='' if bb is None else f'{bb}',
                       color=BIAS_LINE, penwidth='1.1', style='dashed',
                       fontcolor=BIAS_LINE, fontsize='9')

    if legend and biases:
        with g.subgraph(name='cluster_legend') as lg:
            lg.attr(label='', color='grey85', style='rounded')
            lg.node('lw1', shape='point', width='0.01', color='grey55')
            lg.node('lw2', shape='point', width='0.01', color='grey55')
            lg.node('lb1', shape='point', width='0.01', color=BIAS_LINE)
            lg.node('lb2', shape='point', width='0.01', color=BIAS_LINE)
            lg.edge('lw1', 'lw2', label='  weight', color='grey55',
                    penwidth='1.3', fontcolor='grey20', fontsize='9')
            lg.edge('lb1', 'lb2', label='  bias', color=BIAS_LINE,
                    penwidth='1.1', style='dashed',
                    fontcolor=BIAS_LINE, fontsize='9')
    return g


class FFN(nn.Module):
    def __init__(self, in_dim=1, hidden_dims=None, out_dim=1):
        super().__init__()
        hidden_dims = [5] if hidden_dims is None else list(hidden_dims)
        dims = [in_dim] + hidden_dims + [out_dim]
        self.layers = nn.ModuleList(
            nn.Linear(dims[i], dims[i + 1]) for i in range(len(dims) - 1)
        )

    def forward(self, x):
        for layer in self.layers[:-1]:
            x = torch.relu(layer(x))
        return self.layers[-1](x)



def plot_net(model, show_weights=True, figsize=(8, 5)):
    linears = list(model.layers)
    sizes = [linears[0].in_features] + [l.out_features for l in linears]

    h_spacing, v_spacing = 2.0, 1.0
    pos = [[(i * h_spacing, (j - (n - 1) / 2) * v_spacing) for j in range(n)]
           for i, n in enumerate(sizes)]

    fig, ax = plt.subplots(figsize=figsize)

    for i, layer in enumerate(linears):                 # edges
        W = layer.weight.detach().numpy()               # shape (out, in)
        vmax = np.abs(W).max() or 1.0
        for j, (x0, y0) in enumerate(pos[i]):
            for k, (x1, y1) in enumerate(pos[i + 1]):
                w = W[k, j]
                if show_weights:
                    color = "tab:red" if w &lt; 0 else "tab:blue"
                    lw = 3 * abs(w) / vmax
                    alpha = 0.15 + 0.85 * abs(w) / vmax
                else:
                    color, lw, alpha = "gray", 0.8, 0.5
                ax.plot([x0, x1], [y0, y1], color=color, lw=lw, alpha=alpha, zorder=1)

    ytop = (max(sizes) - 1) / 2 * v_spacing + 0.8
    for i, layer_pos in enumerate(pos):                 # nodes + labels
        xs, ys = zip(*layer_pos)
        ax.scatter(xs, ys, s=300, color="white", edgecolors="black",
                   linewidths=1.5, zorder=2)
        name = "input" if i == 0 else "output" if i == len(pos) - 1 else f"hidden {i}"
        ax.text(i * h_spacing, ytop, f"{name}\n({sizes[i]})", ha="center", fontsize=9)

    ax.set_aspect("equal")
    ax.axis("off")
    plt.tight_layout()
    return fig


"""
kink_explorer — two ways to see how ReLU nodes bend a line.

    explorer(w, b, a, c)        interactive widget (Jupyter + Quarto HTML)
    build_animation(w, b, a, c) node-by-node GIF

The widget is plain HTML/CSS/JS rendered inside an iframe, so it needs no
kernel, no extension and no CDN: it keeps working in a static Quarto site.
"""



PALETTE = ["#2a78d6", "#eb6834", "#1baf7a", "#eda100", "#9085e9",
           "#e87ba4", "#008393", "#d24b4b"]

_PAGE = r"""
&lt;style&gt;
  :root { --ink:#1a1a19; --dim:#6b6a66; --line:#e4e2db; --card:#fbfbf9; }
  * { box-sizing:border-box; }
  body { margin:0; padding:14px; font:14px/1.5 ui-sans-serif,-apple-system,"Segoe UI",Roboto,sans-serif;
         color:var(--ink); background:#fff; }
  .bar { display:flex; flex-wrap:wrap; gap:8px; align-items:center; margin-bottom:12px; }
  button, select { font:inherit; color:var(--ink); background:#fff; border:1px solid #d5d3cb;
                   border-radius:7px; padding:6px 11px; cursor:pointer; }
  button:hover { background:#f3f2ee; }
  button:disabled { color:#b9b7b0; cursor:default; background:#fff; }
  .spacer { flex:1; }
  .chk { display:flex; align-items:center; gap:6px; color:var(--dim); cursor:pointer; }
  canvas { width:100%; height:330px; display:block; }
  .stage { display:flex; gap:16px; align-items:flex-start; flex-wrap:wrap; }
  #net { width:236px; flex:none; }
  .plotwrap { flex:1; min-width:320px; }
  .cbias { margin:0 0 10px; }
  .netcap { font-size:12px; color:var(--dim); text-align:center; margin-top:4px; }
  .note { font-size:13px; color:var(--dim); margin:8px 0 0; }
  .eq { font:13px/1.6 ui-monospace,SFMono-Regular,Menlo,monospace; color:var(--dim);
        margin:6px 0 14px; word-break:break-word; }
  .cards { display:grid; grid-template-columns:repeat(auto-fill,minmax(215px,1fr)); gap:10px; }
  .card { border:1px solid var(--line); border-radius:10px; padding:10px 12px; background:var(--card); }
  .head { display:flex; align-items:center; gap:7px; font-weight:600; margin-bottom:8px; }
  .dot { width:10px; height:10px; border-radius:3px; }
  .kink { margin-left:auto; font:12px ui-monospace,monospace; font-weight:400; color:var(--dim); }
  .row { display:grid; grid-template-columns:58px 1fr 46px; align-items:center; gap:8px; margin:5px 0;
         font:12px ui-monospace,monospace; color:var(--dim); }
  .row b { font-weight:400; }
  .row span { text-align:right; color:var(--ink); }
  input[type=range] { width:100%; accent-color:#534AB7; margin:0; }
&lt;/style&gt;

&lt;div class="bar"&gt;
  &lt;select id="act" title="activation function"&gt;&lt;/select&gt;
  &lt;button id="add"&gt;+ node&lt;/button&gt;
  &lt;button id="del"&gt;&minus; node&lt;/button&gt;
  &lt;button id="rnd"&gt;randomise&lt;/button&gt;
  &lt;div class="spacer"&gt;&lt;/div&gt;
  &lt;label class="chk"&gt;&lt;input type="checkbox" id="parts" checked&gt; show each node&lt;/label&gt;
&lt;/div&gt;

&lt;div class="stage"&gt;
  &lt;div id="net"&gt;&lt;/div&gt;
  &lt;div class="plotwrap"&gt;
    &lt;canvas id="cv"&gt;&lt;/canvas&gt;
    &lt;div class="note" id="note"&gt;&lt;/div&gt;
  &lt;/div&gt;
&lt;/div&gt;
&lt;div class="eq" id="eq"&gt;&lt;/div&gt;
&lt;div class="card cbias" id="cbias"&gt;&lt;/div&gt;
&lt;div class="cards" id="cards"&gt;&lt;/div&gt;

&lt;script&gt;
const S = __STATE__;
const PAL = __PALETTE__;
const ACTS = {
  none:       {label:"none (linear)", f:z =&gt; z,                          kinked:false},
  relu:       {label:"ReLU",        f:z =&gt; Math.max(0,z),                 kinked:true},
  leaky_relu: {label:"Leaky ReLU",  f:z =&gt; z&gt;0 ? z : 0.1*z,               kinked:true},
  elu:        {label:"ELU",         f:z =&gt; z&gt;0 ? z : Math.exp(z)-1,       kinked:false},
  softplus:   {label:"Softplus",    f:z =&gt; Math.log1p(Math.exp(-Math.abs(z))) + Math.max(z,0), kinked:false},
  tanh:       {label:"tanh",        f:z =&gt; Math.tanh(z),                  kinked:false},
  sigmoid:    {label:"Sigmoid",     f:z =&gt; 1/(1+Math.exp(-z)),            kinked:false}
};
const XLO = -5, XHI = 5, NX = 700, MAXN = 8;
const SUB = ["\u2081","\u2082","\u2083","\u2084","\u2085","\u2086","\u2087","\u2088"];
const cv = document.getElementById("cv"), ctx = cv.getContext("2d");
const xs = Array.from({length:NX}, (_,i) =&gt; XLO + (XHI-XLO)*i/(NX-1));

const sel = document.getElementById("act");
for (const k in ACTS) sel.add(new Option(ACTS[k].label, k));
sel.value = S.act;

const fmt = v =&gt; (v&lt;0 ? "" : "+") + v.toFixed(2);
const partOf = (n, x) =&gt; n.a * ACTS[S.act].f(n.w*x + n.b);
const yOf = x =&gt; S.nodes.reduce((s,n) =&gt; s + partOf(n,x), S.c);

function draw() {
  const dpr = window.devicePixelRatio || 1, W = cv.clientWidth, H = cv.clientHeight;
  cv.width = W*dpr; cv.height = H*dpr; ctx.setTransform(dpr,0,0,dpr,0,0);
  ctx.clearRect(0,0,W,H);

  const parts = S.nodes.map(n =&gt; xs.map(x =&gt; partOf(n,x)));
  const ys = xs.map(yOf);
  let lo = Math.min(...ys), hi = Math.max(...ys);
  if (S.parts) for (const p of parts) { lo = Math.min(lo, ...p); hi = Math.max(hi, ...p); }
  const pad = 0.12*(hi-lo) + 0.3;
  lo -= pad; hi += pad;

  const L=44, R=12, T=12, B=26;
  const px = x =&gt; L + (x-XLO)/(XHI-XLO)*(W-L-R);
  const py = y =&gt; H-B - (y-lo)/(hi-lo)*(H-T-B);

  ctx.font = "11px ui-monospace, monospace";
  ctx.strokeStyle = "#eeece5"; ctx.fillStyle = "#9b9a94"; ctx.lineWidth = 1;
  ctx.textAlign = "center"; ctx.textBaseline = "top";
  for (let x = XLO; x &lt;= XHI; x++) {
    ctx.beginPath(); ctx.moveTo(px(x),T); ctx.lineTo(px(x),H-B); ctx.stroke();
    ctx.fillText(x, px(x), H-B+6);
  }
  ctx.textAlign = "right"; ctx.textBaseline = "middle";
  const stepY = Math.max(1, Math.round((hi-lo)/6));
  for (let y = Math.ceil(lo/stepY)*stepY; y &lt; hi; y += stepY) {
    ctx.beginPath(); ctx.moveTo(L,py(y)); ctx.lineTo(W-R,py(y)); ctx.stroke();
    ctx.fillText(y, L-7, py(y));
  }
  if (lo &lt; 0 && hi &gt; 0) {
    ctx.strokeStyle = "#d6d4cc";
    ctx.beginPath(); ctx.moveTo(L,py(0)); ctx.lineTo(W-R,py(0)); ctx.stroke();
  }

  const path = vals =&gt; {
    ctx.beginPath();
    vals.forEach((v,i) =&gt; i ? ctx.lineTo(px(xs[i]),py(v)) : ctx.moveTo(px(xs[0]),py(v)));
    ctx.stroke();
  };
  if (S.parts) {
    ctx.lineWidth = 1.5; ctx.setLineDash([]);
    parts.forEach((p,j) =&gt; { ctx.strokeStyle = PAL[j%PAL.length] + "88"; path(p); });
  }
  ctx.lineWidth = 3; ctx.lineJoin = "round"; ctx.strokeStyle = "#3d3691"; path(ys);

  S.nodes.forEach((n,j) =&gt; {
    const k = -n.b/n.w;
    if (S.act === "none" || !isFinite(k) || k &lt;= XLO || k &gt;= XHI) return;
    ctx.strokeStyle = PAL[j%PAL.length] + "66"; ctx.lineWidth = 1; ctx.setLineDash([3,3]);
    ctx.beginPath(); ctx.moveTo(px(k),T); ctx.lineTo(px(k),H-B); ctx.stroke(); ctx.setLineDash([]);
    ctx.beginPath(); ctx.arc(px(k), py(yOf(k)), 4.5, 0, 6.2832);
    ctx.fillStyle = PAL[j%PAL.length]; ctx.fill();
    ctx.strokeStyle = "#fff"; ctx.lineWidth = 2; ctx.stroke();
  });

  const term = n =&gt; S.act === "none"
    ? `${fmt(n.a)}·(${fmt(n.w)}x ${fmt(n.b)})`
    : `${fmt(n.a)}·${ACTS[S.act].label}(${fmt(n.w)}x ${fmt(n.b)})`;
  net();
  document.getElementById("eq").textContent =
    "y = " + fmt(S.c) + " " + S.nodes.map(term).join(" ");
  document.getElementById("note").textContent = S.act === "none"
    ? "No activation: every node is a straight line, so the sum is a straight line too."
      + " Add nodes and the slope changes, never the shape. Switch to ReLU to get a bend."
    : (ACTS[S.act].kinked
        ? "Each node switches on at x = -b/w and tilts the curve by a·w from there on."
        : "A smooth activation rounds the corner off: same bend, no sharp joint.");
}

function net() {
  const n = S.nodes.length, gap = 46, W = 236, H = 34 + n*gap, cy = H/2;
  const xin = 26, xh = 118, xout = 210, r = 14;
  const ny = j =&gt; 17 + gap*(j + 0.5);
  const t = (x,y,s,cls) =&gt; `&lt;text x="${x}" y="${y}" text-anchor="middle" font-size="11"
      font-family="ui-monospace,monospace" fill="${cls}"&gt;${s}&lt;/text&gt;`;
  let g = "";
  S.nodes.forEach((_,j) =&gt; {
    const col = PAL[j%PAL.length], on = S.hl === j, lw = on ? 2.2 : 1;
    g += `&lt;line x1="${xin+r}" y1="${cy}" x2="${xh-r}" y2="${ny(j)}" stroke="${col}"
            stroke-width="${lw}" opacity="${on?1:0.5}"/&gt;
          &lt;line x1="${xh+r}" y1="${ny(j)}" x2="${xout-r}" y2="${cy}" stroke="${col}"
            stroke-width="${lw}" opacity="${on?1:0.5}"/&gt;`;
  });
  S.nodes.forEach((n2,j) =&gt; {
    const col = PAL[j%PAL.length], sub = SUB[j] || "";
    g += `&lt;circle cx="${xh}" cy="${ny(j)}" r="${r}" fill="#fff" stroke="${col}"
            stroke-width="${S.hl===j?2.2:1.2}"/&gt;` +
         t(xh, ny(j)+4, "b"+sub, "#1a1a19") +
         t(xh-32, ny(j)-12, "w"+sub, col) +
         t(xh+32, ny(j)-12, "a"+sub, col);
  });
  g += `&lt;circle cx="${xin}" cy="${cy}" r="${r}" fill="#fff" stroke="#b9b7b0" stroke-width="1.2"/&gt;` +
       t(xin, cy+4, "x", "#1a1a19") +
       `&lt;circle cx="${xout}" cy="${cy}" r="${r}" fill="#fff" stroke="#b9b7b0" stroke-width="1.2"/&gt;` +
       t(xout, cy+4, "c", "#1a1a19") + t(xout, cy+28, "y", "#6b6a66");
  document.getElementById("net").innerHTML =
    `&lt;svg viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="network diagram with
       ${n} hidden nodes, showing where w, b, a and c sit"&gt;&lt;g&gt;${g}&lt;/g&gt;&lt;/svg&gt;
     &lt;div class="netcap"&gt;w, b in layers[0] &middot; a, c in layers[-1]&lt;/div&gt;`;
}

function slider(card, node, key, label) {
  const row = document.createElement("div");
  row.className = "row";
  row.innerHTML = `&lt;b&gt;${label}&lt;/b&gt;&lt;input type="range" min="-3" max="3" step="0.05"&gt;&lt;span&gt;&lt;/span&gt;`;
  const inp = row.querySelector("input"), out = row.querySelector("span");
  inp.value = node[key]; out.textContent = fmt(node[key]);
  inp.addEventListener("input", () =&gt; {
    node[key] = +inp.value; out.textContent = fmt(node[key]);
    const kk = card.querySelector(".kink");
    if (kk) kk.textContent = kinkLabel(node);
    draw();
  });
  card.appendChild(row);
}

const kinkLabel = n =&gt; S.act === "none" ? "no bend"
  : (ACTS[S.act].kinked ? "kink " : "bend ")
    + (Math.abs(n.w) &lt; 1e-6 ? "—" : "x=" + (-n.b/n.w).toFixed(2));

function cards() {
  const cb = document.getElementById("cbias");
  cb.innerHTML = `&lt;div class="head"&gt;&lt;span class="dot" style="background:#b9b7b0"&gt;&lt;/span&gt;
    output bias&lt;span class="kink"&gt;c &mdash; shifts the whole curve up or down&lt;/span&gt;&lt;/div&gt;`;
  slider(cb, S, "c", "c");
  const box = document.getElementById("cards");
  box.textContent = "";
  S.nodes.forEach((n,j) =&gt; {
    const card = document.createElement("div");
    card.className = "card";
    card.innerHTML = `&lt;div class="head"&gt;&lt;span class="dot" style="background:${PAL[j%PAL.length]}"&gt;&lt;/span&gt;
      node ${j+1}&lt;span class="kink"&gt;${kinkLabel(n)}&lt;/span&gt;&lt;/div&gt;`;
    slider(card, n, "w", "w");
    slider(card, n, "b", "b");
    slider(card, n, "a", "a out");
    card.onmouseenter = () =&gt; { S.hl = j; net(); };
    card.onmouseleave = () =&gt; { S.hl = -1; net(); };
    box.appendChild(card);
  });
  document.getElementById("add").disabled = S.nodes.length &gt;= MAXN;
  document.getElementById("del").disabled = S.nodes.length &lt;= 1;
  draw();
}

const rand = () =&gt; +(Math.random()*4 - 2).toFixed(2);
document.getElementById("add").onclick = () =&gt; {
  S.nodes.push(S.pool.length ? S.pool.shift() : {w:rand(), b:rand(), a:rand()});
  cards();
};
document.getElementById("del").onclick = () =&gt; { S.pool.unshift(S.nodes.pop()); cards(); };
document.getElementById("rnd").onclick = () =&gt; {
  S.nodes.forEach(n =&gt; { n.w = rand(); n.b = rand(); n.a = rand(); });
  S.c = +(Math.random()-0.5).toFixed(2); cards();
};
sel.onchange = () =&gt; { S.act = sel.value; cards(); };
document.getElementById("parts").onchange = e =&gt; { S.parts = e.target.checked; draw(); };
window.addEventListener("resize", draw);
cards();
&lt;/script&gt;
"""


class _Widget:
    """Anything with _repr_html_ renders in Jupyter, nbconvert and Quarto alike."""

    def __init__(self, html):
        self.html = html

    def _repr_html_(self):
        return self.html


def explorer(w=None, b=None, a=None, c=0.0, act="none", start_nodes=1, height=700):
    """Interactive explorer.

    Starts with one node and no activation, i.e. a plain straight line: switching the
    dropdown to ReLU is what puts the first bend in it. `start_nodes` sets how many of
    the nodes you pass are visible at the start; the rest wait in a pool that the
    "+ node" button draws from before it starts inventing random ones.
    """
    import json
    from html import escape                      # local, so a partial paste still runs

    if w is None:
        w, b, a = [1.0, 1.0, -1.0], [1.0, -1.5, -2.0], [1.0, -1.6, 1.2]
    nodes = [{"w": round(float(wi), 2), "b": round(float(bi), 2), "a": round(float(ai), 2)}
             for wi, bi, ai in zip(w, b, a)]
    n = max(1, min(start_nodes, len(nodes)))
    state = {"nodes": nodes[:n], "pool": nodes[n:], "c": round(float(c), 2),
             "act": act, "parts": True, "hl": -1}
    page = (_PAGE.replace("__STATE__", json.dumps(state))
                 .replace("__PALETTE__", json.dumps(PALETTE)))
    return _Widget(f'&lt;iframe srcdoc="{escape(page)}" width="100%" height="{height}" '
                   f'style="border:1px solid #e4e2db;border-radius:12px" loading="lazy"&gt;&lt;/iframe&gt;')


def build_animation(w, b, a, c, out="relu_build.gif", x=None, fps=20, per_node=26, grow=18):
    """Add one node at a time and save a GIF of the curve gaining a kink each time."""
    import matplotlib.pyplot as plt
    from matplotlib.animation import FuncAnimation, PillowWriter

    w, b, a = map(np.asarray, (w, b, a))
    k = -b / w
    if x is None:
        lo, hi = np.clip([k.min(), k.max()], -10, 10)
        x = np.linspace(lo - 1.5, hi + 1.5, 700)
    h = a[:, None] * np.maximum(w[:, None] * x + b[:, None], 0)
    p = c + np.vstack([np.zeros_like(x), np.cumsum(h, 0)])

    fig, ax = plt.subplots(figsize=(7.5, 4.6), dpi=120)
    fig.patch.set_facecolor("white")
    ax.set_facecolor("#fcfcfb")
    ax.grid(color="#eeece5", lw=1)
    ax.set_axisbelow(True)
    ax.spines[["top", "right"]].set_visible(False)
    ax.spines[["left", "bottom"]].set_color("#d6d4cc")
    ax.tick_params(colors="#9b9a94", labelsize=9)
    ax.plot(x, p[-1], "--", lw=1.3, color="#c9c7c0", label=f"all {len(w)} nodes")
    (line,) = ax.plot([], [], lw=3, color="#3d3691", solid_joinstyle="round")
    (dots,) = ax.plot([], [], "o", ms=8, mfc="#1baf7a", mec="white", mew=2, zorder=5)
    ax.set(xlim=(x[0], x[-1]), ylim=(p.min() - 0.6, p.max() + 0.6), xlabel="x", ylabel="y")
    ax.legend(loc="upper left", fontsize=9, frameon=False)

    def frame(i):
        j, t = divmod(i, per_node)
        y = p[j] + min(t / grow, 1) * h[j]
        line.set_data(x, y)
        done = k[: j + (t &gt;= grow)]
        vis = done[(done &gt; x[0]) & (done &lt; x[-1])]
        dots.set_data(vis, np.interp(vis, x, y))
        ax.set_title(f"node {j+1} of {len(w)}    kink at x = {k[j]:+.2f},"
                     f"    slope change {a[j]*w[j]:+.2f}",
                     loc="left", fontsize=11, color="#1a1a19", family="monospace")
        return line, dots

    anim = FuncAnimation(fig, frame, frames=len(w) * per_node)
    anim.save(out, writer=PillowWriter(fps=fps))
    plt.close(fig)
    return out


def build_slider(w, b, a, c, x=None, height=520):
    """Plotly version of the build-up: a slider the reader scrubs instead of a GIF."""
    import plotly.graph_objects as go

    w, b, a = map(np.asarray, (w, b, a))
    n = len(w)
    k = -b / w
    if x is None:
        lo, hi = np.clip([k.min(), k.max()], -10, 10)
        x = np.linspace(lo - 1.5, hi + 1.5, 500)
    h = a[:, None] * np.maximum(w[:, None] * x + b[:, None], 0)
    p = c + np.vstack([np.zeros_like(x), np.cumsum(h, 0)])

    fig = go.Figure()
    fig.add_scatter(x=x, y=p[-1], mode="lines", name=f"all {n} nodes",
                    line=dict(color="#c9c7c0", width=1.5, dash="dash"), hoverinfo="skip")
    for j in range(n + 1):
        fig.add_scatter(x=x, y=p[j], mode="lines", visible=(j == 0), showlegend=False,
                        line=dict(color="#3d3691", width=3),
                        hovertemplate="x %{x:.2f}&lt;br&gt;y %{y:.2f}&lt;extra&gt;&lt;/extra&gt;")
        vis = k[:j][(k[:j] &gt; x[0]) & (k[:j] &lt; x[-1])]
        fig.add_scatter(x=vis, y=np.interp(vis, x, p[j]), mode="markers",
                        visible=(j == 0), showlegend=False,
                        marker=dict(size=11, color="#1baf7a",
                                    line=dict(color="white", width=2)),
                        hovertemplate="kink at x %{x:.2f}&lt;extra&gt;&lt;/extra&gt;")

    steps = []
    for j in range(n + 1):
        label = "bias only" if j == 0 else f"{j} node" + ("s" if j &gt; 1 else "")
        vis = [True] + [i // 2 == j for i in range(2 * (n + 1))]
        note = "" if j == 0 else (f"    kink at x = {k[j-1]:+.2f},"
                                  f"  slope change {a[j-1] * w[j-1]:+.2f}")
        steps.append(dict(method="update", label=label,
                          args=[{"visible": vis}, {"title.text": label + note}]))

    fig.update_layout(
        template="simple_white", height=height, hovermode="x unified",
        title=dict(text="bias only", font=dict(family="monospace", size=14), x=0),
        margin=dict(l=60, r=30, t=60, b=90),
        xaxis=dict(title="x", range=[x[0], x[-1]], showgrid=True, gridcolor="#eeece5"),
        yaxis=dict(title="y", range=[p.min() - 0.6, p.max() + 0.6],
                   showgrid=True, gridcolor="#eeece5"),
        legend=dict(x=0.01, y=0.99, bgcolor="rgba(0,0,0,0)"),
        sliders=[dict(active=0, steps=steps, pad=dict(t=40),
                      currentvalue=dict(prefix="showing: ", font=dict(size=13)))],
    )
    return fig


def make_data(n=2000, x_range=(-10.0, 10.0), func=None, noise=0.05, seed=0):
    g = torch.Generator().manual_seed(seed)
    lo, hi = x_range
    x = torch.rand(n, 1, generator=g) * (hi - lo) + lo
    if not func:
        y_clean = torch.sinc(x / torch.pi)              # = sin(x)/x, safe at x=0
    else:
        y_clean = func(x)
    y = y_clean + noise * torch.randn(y_clean.shape, generator=g)
    return x, y, y_clean


# ---- config ------------------------------------------------------------
XLO, XHI = -10.0, 10.0
EPOCHS, SNAP = 4000, 25
N_PLOT = 600

# Order traces are added to the figure. Frames replace only the animated
# ones, so their indices are derived here instead of hard-coded.
TRACE_NAMES = ('train data', 'sinc', 'network', 'hinges', 'train loss', 'val loss')
ANIMATED = [TRACE_NAMES.index(n) for n in ('network', 'hinges', 'train loss', 'val loss')]


# ---- data --------------------------------------------------------------
def plot_grid(xlo=XLO, xhi=XHI, n=N_PLOT):
    """Dense grid used only for drawing; the data itself stays unsorted."""
    x = torch.linspace(xlo, xhi, n).unsqueeze(1)
    return x, x.squeeze().numpy()


def target(x):
    """Ground-truth sin(x)/x on a column tensor, as a 1-D numpy array."""
    return torch.sinc(x / torch.pi).squeeze().numpy()


# ---- model introspection ----------------------------------------------
@torch.no_grad()
def hinges(model, xlo=XLO, xhi=XHI):
    """Kink locations of a 1-D single-hidden-layer ReLU net.

    Fixed-length output; dead or out-of-range units become NaN (Plotly skips them).
    """
    w = model.layers[0].weight[:, 0]
    b = model.layers[0].bias
    nan = torch.full_like(w, float('nan'))
    k = torch.where(w.abs() &gt; 1e-8, -b / w, nan)
    k = torch.where((k &gt;= xlo) & (k &lt;= xhi), k, nan)
    yk = model(torch.nan_to_num(k, nan=0.0).unsqueeze(1))[:, 0]
    yk = torch.where(torch.isnan(k), torch.full_like(yk, float('nan')), yk)
    return k.numpy(), yk.numpy()


# ---- training ----------------------------------------------------------
def train_step(model, opt, lossf, x, y):
    model.train()
    opt.zero_grad()
    loss = lossf(model(x), y)
    loss.backward()
    opt.step()
    return loss.item()


@torch.no_grad()
def eval_loss(model, lossf, x, y):
    model.eval()
    return lossf(model(x), y).item()


@torch.no_grad()
def snapshot(model, epoch, x_plot, xs, tr_hist, va_hist):
    """One animation frame: fitted curve, hinge markers, and both loss curves."""
    yp = model(x_plot)[:, 0].numpy()
    kx, ky = hinges(model)
    ep = np.arange(1, epoch + 1)
    return go.Frame(
        name=str(epoch),
        data=[go.Scatter(x=xs, y=yp),
              go.Scatter(x=kx, y=ky),
              go.Scatter(x=ep, y=np.array(tr_hist)),
              go.Scatter(x=ep, y=np.array(va_hist))],
        traces=ANIMATED,
        layout=go.Layout(title_text=(
            f"epoch {epoch} — train {tr_hist[-1]:.4f} · val {va_hist[-1]:.4f}")))


def train(model, opt, lossf, train_set, val_set, x_plot, xs,
          epochs=EPOCHS, snap=SNAP):
    """Full-batch training loop; returns loss histories and animation frames."""
    x_train, y_train = train_set
    x_val, y_val = val_set
    tr_hist, va_hist, frames = [], [], []

    for epoch in tqdm(range(1, epochs + 1)):
        tr_hist.append(train_step(model, opt, lossf, x_train, y_train))
        va_hist.append(eval_loss(model, lossf, x_val, y_val))
        if epoch == 1 or epoch % snap == 0:
            frames.append(snapshot(model, epoch, x_plot, xs, tr_hist, va_hist))

    return tr_hist, va_hist, frames


# ---- figure ------------------------------------------------------------
def add_fit_traces(fig, train_set, xs, y_true, first_frame):
    """Left panel: data, target, current fit, hinge markers."""
    x_train, y_train = train_set
    fig.add_trace(go.Scatter(x=x_train.squeeze().numpy(), y=y_train.squeeze().numpy(),
                             mode='markers', name='train data',
                             marker=dict(color='#2a78d6', size=6, opacity=0.75)),
                  row=1, col=1)
    fig.add_trace(go.Scatter(x=xs, y=y_true, mode='lines', name='sin(x)/x',
                             line=dict(color='gray', width=2, dash='dot')),
                  row=1, col=1)
    fig.add_trace(go.Scatter(x=xs, y=first_frame.data[0].y, mode='lines', name='network',
                             line=dict(color='black', width=2.5)),
                  row=1, col=1)
    fig.add_trace(go.Scatter(x=first_frame.data[1].x, y=first_frame.data[1].y,
                             mode='markers', name='hinges',
                             marker=dict(color='black', size=9,
                                         line=dict(color='white', width=1.5)),
                             hovertemplate='hinge at x = %{x:.3f}&lt;extra&gt;&lt;/extra&gt;'),
                  row=1, col=1)


def add_loss_traces(fig, tr_hist, va_hist):
    """Right panel: the two loss curves, seeded with their first point."""
    fig.add_trace(go.Scatter(x=[1], y=[tr_hist[0]], mode='lines', name='train loss',
                             line=dict(color='#2a78d6', width=2)), row=1, col=2)
    fig.add_trace(go.Scatter(x=[1], y=[va_hist[0]], mode='lines', name='val loss',
                             line=dict(color='#eb6834', width=2)), row=1, col=2)


def loss_log_range(tr_hist, va_hist, pad_lo=0.7, pad_hi=1.4):
    lo = min(min(tr_hist), min(va_hist)) * pad_lo
    hi = max(max(tr_hist), max(va_hist)) * pad_hi
    return [np.log10(lo), np.log10(hi)]


def animation_controls(frames):
    """Play/pause buttons and the epoch slider."""
    updatemenus = [dict(
        type='buttons', direction='left', x=0, y=-0.18, xanchor='left',
        buttons=[
            dict(label='▶', method='animate',
                 args=[None, dict(frame=dict(duration=40, redraw=True),
                                  fromcurrent=True, transition=dict(duration=0))]),
            dict(label='❚❚', method='animate',
                 args=[[None], dict(frame=dict(duration=0, redraw=False),
                                    mode='immediate')])])]
    sliders = [dict(
        active=0, x=0.12, len=0.88, y=-0.12,
        currentvalue=dict(prefix='epoch '),
        steps=[dict(method='animate', label=fr.name,
                    args=[[fr.name], dict(mode='immediate',
                                          frame=dict(duration=0, redraw=True),
                                          transition=dict(duration=0))])
               for fr in frames])]
    return updatemenus, sliders


def build_figure(train_set, xs, y_true, tr_hist, va_hist, frames,
                 xlo=XLO, xhi=XHI, epochs=EPOCHS):
    fig = make_subplots(rows=1, cols=2, subplot_titles=('fit', 'loss'),
                        column_widths=[0.6, 0.4])

    add_fit_traces(fig, train_set, xs, y_true, frames[0])
    add_loss_traces(fig, tr_hist, va_hist)
    fig.frames = frames

    fig.update_xaxes(title_text='x', range=[xlo, xhi], row=1, col=1)
    fig.update_yaxes(title_text='y', range=[-0.7, 1.5], row=1, col=1)
    fig.update_xaxes(title_text='epoch', range=[0, epochs], row=1, col=2)
    fig.update_yaxes(title_text='MSE', type='log',
                     range=loss_log_range(tr_hist, va_hist), row=1, col=2)

    updatemenus, sliders = animation_controls(frames)
    fig.update_layout(
        template='simple_white', height=600, autosize=True,
        title=f"epoch 1 — train {tr_hist[0]:.4f} · val {va_hist[0]:.4f}",
        legend=dict(orientation='h', y=1.12, x=0),
        updatemenus=updatemenus, sliders=sliders)
    return fig


# ---- orchestration -----------------------------------------------------
def run(train_set, val_set, model=None, hidden_dims=(5,), lr=1e-2,
        epochs=EPOCHS, snap=SNAP, seed=0):
    torch.manual_seed(seed)
    x_plot, xs = plot_grid()
    y_true = target(x_plot)

    if not model: 
        model = FFN(hidden_dims=list(hidden_dims))
    opt = torch.optim.Adam(model.parameters(), lr=lr)
    lossf = nn.MSELoss()

    tr_hist, va_hist, frames = train(model, opt, lossf, train_set, val_set,
                                     x_plot, xs, epochs=epochs, snap=snap)
    fig = build_figure(train_set, xs, y_true, tr_hist, va_hist, frames,
                       epochs=epochs)
    return fig, model


