    [['&lt;&lt;I&gt;w&lt;/I&gt;&lt;SUB&gt;21&lt;/SUB&gt;&gt;'],
     ['&lt;&lt;I&gt;w&lt;/I&gt;&lt;SUB&gt;22&lt;/SUB&gt;&gt;']],
]
biases = [
    ['&lt;&lt;I&gt;b&lt;/I&gt;&lt;SUB&gt;1&lt;/SUB&gt;&gt;', '&lt;&lt;I&gt;b&lt;/I&gt;&lt;SUB&gt;2&lt;/SUB&gt;&gt;'],
    ['&lt;&lt;I&gt;b&lt;/I&gt;&lt;SUB&gt;3&lt;/SUB&gt;&gt;'],
]

